/**
 * @name URL or header injection
 * @description User-controlled data flowing into URLs or headers without validation can lead to injection attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/url-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UrlHeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("urllib").getMember("parse").getMember(["parse_qs", "parse_qsl", "urlparse"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "patch", "request"]).getACall() or
        call.getFunction().asExpr().(Attribute).getName() in ["get", "post", "put", "delete", "patch", "request"]
      ) and
      sink = call.getArg(0)
    )
  }
}

module UrlHeaderInjectionFlow = TaintTracking::Global<UrlHeaderInjectionConfig>;
import UrlHeaderInjectionFlow::PathGraph

from UrlHeaderInjectionFlow::PathNode source, UrlHeaderInjectionFlow::PathNode sink
where UrlHeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential URL injection from $@.", source.getNode(), "parsed URL data"
